<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\{Branch,Category,Product}; use Illuminate\Http\Request;
class CatalogController extends Controller { public function branches(){return Branch::where('is_active',true)->get();} public function categories(){return Category::where('is_active',true)->orderBy('sort_order')->get();} public function products(Request $r){$q=Product::with(['category','options'])->where('is_active',true); if($r->filled('category_id'))$q->where('category_id',$r->integer('category_id')); if($r->filled('search'))$q->where('name','like','%'.$r->string('search').'%'); if($r->filled('branch_id'))$q->whereHas('branches',fn($b)=>$b->where('branches.id',$r->integer('branch_id'))->where('branch_product.is_available',true)); return $q->latest()->paginate(20);} public function show(Product $product){return $product->load('category','options','branches');} }